/* setbuf(stream, buffer) */

/* Disable buffering for stderr.
   Error output appears immediately (unbuffered mode). */
setbuf(stderr, NULL);

/* Output is guaranteed instantaneous, often crucial
   for crash logging or console interactivity. */
fprintf(stderr, "Log entry 001.");
fflush(stderr);
/* If a buffer was used: char buf[BUFSIZ]; setbuf(stdout, buf); */
